        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "To know oneself is, above all, to know what one lacks. It is to measure oneself against Truth, and not the other way around.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "There is something in us, as storytellers and as listeners to stories, that demands the redemptive act, that demands that what falls at least be offered the chance to be restored.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "The writer operates at a peculiar crossroads where time and place and eternity somehow meet. His problem is to find that location.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "I feel that discussing story-writing in terms of plot, character, and theme is like trying to describe the expression on a face by saying where the eyes, nose, and mouth are.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "A story is a way to say something that can't be said any other way, and it takes every word in the story to say what the meaning is.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "I believe that the basic experience of everyone is the experience of human limitation.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "The main concern of the fiction writer is with mystery as it is incarnated in real life.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "stories are considered not quite as satisfying as statements and statements not quite as satisfying as statistics; but in the long run, a people is known, not by its statements or its statistics, but by the stories it tells.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "I find that most people know what a story is until they sit down to write one.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "The way to despair is to refuse to have any kind of experience.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "No art is sunk in the self, but rather, in art the self becomes self-forgetful in order to meet the demands of the thing seen and the thing being made.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "There may never be anything new to say, but there is always a new way to say it, and since, in art, the way of saying a thing becomes a part of what is said, every work of art is unique and requires fresh attention.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "The beginning of human knowledge is through the senses, and the fiction writer begins where the human perception begins. He appeals through the senses, and you cannot appeal through the senses with abstractions.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "Fiction is about everything human and we are made out of dust, and if you scorn getting yourself dusty, then you shouldn't write fiction. It isn't grand enough for you.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "The Negro will in the matter of a few years have his constitutional rights and we will all then see that the business of getting along with each other is much the same as it has always been, even though new manners are called for. The fiction writer is interested in individuals, not races; he knows that good and evil are not apportioned along racial lines and when he deals with topical matters, if he is any good, he sees the long run through the short run.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "The short story writer particularly has to learn to read life in a way that includes the most possibilities--like the medieval commentators on scripture, who found three kinds of meaning in the literal level of the sacred text. If you see things in depth, you will be more liable to write them that way.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "I don't think you should write something as long as a novel around anything that is not of the gravest concern to you and everybody else and for me this is always the conflict between an attraction for the Holy and the disbelief in it that we breathe in with the air of the times.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "All human nature vigorously resists grace because grace changes us and the change is painful.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "I come from a family where the only emotion respectable to show is irritation. In some this tendency produces hives, in others literature, in me both.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "It is hard to make your adversaries real people unless you recognize yourself in them - in which case, if you don't watch out, they cease to be adversaries.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "The novel is an art form and when you use it for anything other than art, you pervert it....If you manage to use it successfully for social, religious, or other purposes, it is because you make it art first.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "The truth does not change according to our ability to stomach it emotionally.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "Conviction without experience makes for harshness.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "charity is beyond reason, and that God can be known through charity.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "About the only way we know whether we believe or not is by what we do", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "One result of the stimulation of your intellectual life that takes place in college is usually a shrinking of the imaginative life. This sounds like a paradox, but I have often found it to be true.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "Faith is what you have in the absence of knowledge. The reason this clash doesn't bother me any longer is because I have got, over the years, a sense of the immense sweep of creation, of the evolutionary process in everything, of how incomprehensible God must necessarily be to be the God of heaven and earth. You can't fit the Almighty into your intellectual categories.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "If you want your faith, you have to work for it. It is a gift, but for very few is it a gift given without any demand for equal time devoted to its cultivation. For every book you read that is anti-Christian, make it your business to read one that presents the other side of the picture; if one isn't satisfactory read others. Don't think that you I have to abandon reason to be a Christian.", Author = "Flannery O'Connor" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Flannery_O'Connor", Text = "Even in the life of a Christian, faith rises and falls like the tides of an invisible sea. It's there, even when he can't see it or feel it, if he wants it to be there. You realize, I think, that it is more valuable, more mysterious, altogether more immense than anything you can learn or decide upon in college. Learn what you can, but cultivate Christian scepticism. It will keep you free-not free to do anything you please, but free to be formed by something larger than your own intellect or the intellects of those around you.", Author = "Flannery O'Connor" },
